import { Type } from "typebox";
import { saveKnowledge, getKnowledge, listKnowledge, searchKnowledge, deleteKnowledge } from "./tools/brain.js";
import { logSession, updateProgress, sessionStart, sessionEnd } from "./tools/session.js";
import { getProjectContext, setProjectContext, setNextSteps } from "./tools/project.js";
export default function (pi) {
    const $ = (fn) => async (_id, params) => ({ details: {}, content: [{ type: "text", text: fn(params) }] });
    pi.registerTool({ name: "get_project_context", label: "Get Project Context", description: "Get project README and today's session", promptSnippet: "Load project context and session from vault", parameters: Type.Object({ cwd: Type.String() }), execute: $(getProjectContext) });
    pi.registerTool({ name: "log_session", label: "Log Session", description: "Structured session log", promptSnippet: "Log structured session entry with work table, discoveries, warnings", parameters: Type.Object({ cwd: Type.String(), title: Type.String(), summary: Type.String(), items: Type.Optional(Type.Array(Type.Object({ item: Type.String(), detail: Type.String() }))), discoveries: Type.Optional(Type.Array(Type.String())), warnings: Type.Optional(Type.Array(Type.String())), tips: Type.Optional(Type.Array(Type.String())), next_session: Type.Optional(Type.String()), diagram: Type.Optional(Type.String()) }), execute: $(logSession) });
    pi.registerTool({ name: "update_progress", label: "Update Progress", description: "Quick mid-session note", promptSnippet: "Append a timestamped progress note", parameters: Type.Object({ cwd: Type.String(), text: Type.String() }), execute: $(updateProgress) });
    pi.registerTool({ name: "session_start", label: "Session Start", description: "Create README + today's session file. Wrap with log_session for the structured summary.", promptSnippet: "Create project README and session file", parameters: Type.Object({ cwd: Type.String(), goal: Type.Optional(Type.String()) }), execute: $(sessionStart) });
    pi.registerTool({ name: "session_end", label: "Session End", description: "Quick end-of-session summary line. Prefer log_session for structured wrap-ups.", promptSnippet: "Log end-of-session summary", parameters: Type.Object({ cwd: Type.String(), summary: Type.String() }), execute: $(sessionEnd) });
    pi.registerTool({ name: "save_knowledge", label: "Save Knowledge", description: "Save brain knowledge, merges with existing", promptSnippet: "Save structured brain knowledge that auto-merges", parameters: Type.Object({ cwd: Type.String(), topic: Type.String(), summary: Type.String(), sections: Type.Optional(Type.Array(Type.Object({ heading: Type.String(), content: Type.String() }))), items: Type.Optional(Type.Array(Type.Object({ item: Type.String(), detail: Type.String() }))), discoveries: Type.Optional(Type.Array(Type.String())), warnings: Type.Optional(Type.Array(Type.String())), tips: Type.Optional(Type.Array(Type.String())), questions: Type.Optional(Type.Array(Type.String())), tasks: Type.Optional(Type.Array(Type.String())), diagram: Type.Optional(Type.String()), patterns: Type.Optional(Type.Array(Type.Object({ name: Type.String(), language: Type.Optional(Type.String()), code: Type.String() }))) }), execute: $(saveKnowledge) });
    pi.registerTool({ name: "get_knowledge", label: "Get Knowledge", description: "Read a brain note", promptSnippet: "Read a brain knowledge topic", parameters: Type.Object({ cwd: Type.String(), topic: Type.Optional(Type.String()) }), execute: $(getKnowledge) });
    pi.registerTool({ name: "list_knowledge", label: "List Knowledge", description: "List all brain topics", promptSnippet: "List all brain knowledge topics", parameters: Type.Object({ cwd: Type.String() }), execute: $(listKnowledge) });
    pi.registerTool({ name: "search_knowledge", label: "Search Knowledge", description: "Search all brain notes at once", promptSnippet: "Search all brain notes for a query", parameters: Type.Object({ cwd: Type.String(), query: Type.String(), case_sensitive: Type.Optional(Type.Boolean()) }), execute: $(searchKnowledge) });
    pi.registerTool({ name: "delete_knowledge", label: "Delete Knowledge", description: "Move a brain note to brain/.trash/", promptSnippet: "Trash a brain note", parameters: Type.Object({ cwd: Type.String(), topic: Type.String() }), execute: $(deleteKnowledge) });
    pi.registerTool({ name: "set_next_steps", label: "Set Next Steps", description: "Update README next steps", promptSnippet: "Update next steps in project README", parameters: Type.Object({ cwd: Type.String(), steps: Type.String() }), execute: $(setNextSteps) });
    pi.registerTool({ name: "set_project_context", label: "Set Project Context", description: "Update README context section", promptSnippet: "Update project context in README", parameters: Type.Object({ cwd: Type.String(), context: Type.String() }), execute: $(setProjectContext) });
}
